// Privacy date: 16.08.2026 (locale-formatted). No unverified data location claims.

export const PRIVACY_DATE = '2026-08-16';

function formatDate(dateStr, lang) {
  const d = new Date(dateStr);
  const localeMap = { en: 'en-GB', de: 'de-DE', es: 'es-ES', bg: 'bg-BG' };
  return d.toLocaleDateString(localeMap[lang] || 'en-GB', { year: 'numeric', month: 'long', day: 'numeric' });
}

export function getPrivacyDate(lang) {
  return formatDate(PRIVACY_DATE, lang);
}

